    tagline: '増減するのは労災保険率（有期は確定保険料）だけ。継続・建設有期・立木伐採有期で規模要件が違う。建設と立木の違いは規模の測り方（請負金額 vs 素材生産量）だけ。増減幅は原則±40%。',
