    note: '役員の任期は協会＝3年。協会の理事長に事故・欠員のときは理事長があらかじめ指名する理事が代理（理事の互選ではない）。会計監査人は厚労大臣が選任。重要な財産の処分はどちらも厚労大臣の認可で共通。',
    cards: [
      { q: "【健康保険法】協会は、毎事業年度、財務諸表を作成し、これに当該事業年度の事業報告書及び決算報告書を添え、監事及び厚生労働大臣が選任する会計監査人の意見を付けて、決算完結後2か月以内に厚生労働大臣に提出し、その承認を受けなければならない。", a: "○ 健保の私が整理するわね。協会の決算は、財務諸表に事業報告書・決算報告書を添えて、[[決算完結後2か月以内に厚生労働大臣へ提出して承認]]を受けるの。会計監査人は[[厚生労働大臣が選任]]するわ。だから○ね。", p: "協会の決算＝決算完結後2か月以内に厚労大臣へ提出・承認。会計監査人は厚労大臣が選任。" },
      { q: "【健康保険法】協会は、役員として、理事長1人、理事6人以内及び監事2人を置く。役員の任期は3年とする。理事長に事故があるとき、又は理事長が欠けたときは、理事の互選により選ばれた者がその職務を代理し、又はその職務を行う。", a: "× 健保の私が整理するわね。前半は正しいの（理事長1人・理事6人以内・監事2人、任期3年）。でも理事長の職務代理は[[「理事の互選」ではなく、理事長があらかじめ指名する理事]]が行うのよ。だから×ね。", p: "協会の理事長代理は、理事長があらかじめ指名する理事（理事の互選ではない）。" },
      { q: "【健康保険法】健康保険組合の監事は、組合会において、健康保険組合が設立された適用事業所（設立事業所）の事業主の選定した組合会議員及び被保険者である組合員の互選した組合会議員のうちから、それぞれ1人を選挙で選出する。なお、監事は、健康保険組合の理事又は健康保険組合の職員と兼ねることができない。", a: "○ 健保の私が整理するわね。組合の監事は、組合会で[[事業主側の組合会議員と被保険者側の組合会議員から、それぞれ1人ずつ選挙]]で選ぶの（計2人）。[[監事は理事や職員と兼ねられない]]わ。だから○ね。", p: "組合の監事は組合会で事業主側・被保険者側からそれぞれ1人を選挙。理事・職員と兼任不可。" },
      { q: "【健康保険法】健康保険法第7条の14によると、厚生労働大臣又は全国健康保険協会理事長は、それぞれその任命に係る全国健康保険協会の役員が、心身の故障のため職務の遂行に堪えないと認められるとき、又は職務上の義務違反があるときのいずれかに該当するとき、その他役員たるに適しないと認めるときは、その役員を解任することができる。また、全国健康保険協会理事長は、当該規定により全国健康保険協会理事を解任したときは、遅滞なく、厚生労働大臣に届け出るとともに、これを公表しなければならない。", a: "○ 健保の私が整理するわね。協会の役員は、[[任命した側（大臣は理事長・監事、理事長は理事）が、心身の故障・義務違反等のときに解任]]できるの。理事長が理事を解任したら[[遅滞なく厚生労働大臣へ届出・公表]]するわ。だから○ね。", p: "協会の役員は任命者が解任できる。理事長が理事を解任したら厚労大臣へ届出・公表。" },
    ],
